def maxVowels(s: str, k: int) -> int:
    vowels = {'a', 'e', 'i', 'o', 'u'}
    vowel_count = 0

    # Count vowels in the first window of size k
    for i in range(k):
        if s[i] in vowels:
            vowel_count += 1

    max_vowels = vowel_count

    # Slide the window: one character enters, one leaves
    for i in range(k, len(s)):
        if s[i] in vowels:
            vowel_count += 1
        if s[i - k] in vowels:
            vowel_count -= 1
        if vowel_count > max_vowels:
            max_vowels = vowel_count

    return max_vowels
